def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if not alive_opponents:
        if hp <= 2 or no_water_days >= 1:
            return float(min(budget, DAILY_SALARY * 0.9))
        return float(min(budget, DAILY_SALARY * 0.25))

    prev_bids = []
    pressure_scores = []
    needy_count = 0
    rich_count = 0

    for opp in alive_opponents:
        obudget = opp.get('budget', 0)
        ohp = opp.get('hp', 0)
        onwd = opp.get('no_water_days', 0)
        if obudget >= DAILY_SALARY * 2:
            rich_count += 1
        if ohp <= 3 or onwd >= 1:
            needy_count += 1

        prev = opp.get('previous_trace', {}) or {}
        pbid = prev.get('bid')
        if pbid is not None:
            prev_bids.append(float(pbid))
            score = float(pbid)
            if prev.get('status') != 'ok':
                score *= 0.85
            if prev.get('supply') is not None and prev.get('supply') <= 17:
                score *= 0.95
            pressure_scores.append(score)

    if prev_bids:
        highest_prev = max(prev_bids)
        avg_prev = sum(prev_bids) / len(prev_bids)
    else:
        highest_prev = DAILY_SALARY * 0.7
        avg_prev = DAILY_SALARY * 0.55

    est_pressure = max(pressure_scores) if pressure_scores else avg_prev

    supply_factor = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if supply >= 23:
        base = DAILY_SALARY * 0.28
    elif supply >= 20:
        base = DAILY_SALARY * 0.42
    elif supply >= 17:
        base = DAILY_SALARY * 0.58
    else:
        base = DAILY_SALARY * 0.78

    urgency = 0.0
    if hp <= 2:
        urgency += DAILY_SALARY * 0.42
    elif hp <= 4:
        urgency += DAILY_SALARY * 0.22

    if no_water_days >= 2:
        urgency += DAILY_SALARY * 0.35
    elif no_water_days >= 1:
        urgency += DAILY_SALARY * 0.18

    urgency += needy_count * 2.0
    urgency += rich_count * 1.5
    urgency += supply_factor * 10.0

    target = max(base + urgency, avg_prev * 0.72)

    if highest_prev >= 180:
        if hp >= 5 and no_water_days == 0 and supply >= 20:
            target = min(target, DAILY_SALARY * 0.38)
        else:
            target = max(target, min(highest_prev * 0.55, DAILY_SALARY * 1.05))
    elif highest_prev >= 110:
        if hp >= 6 and no_water_days == 0 and supply >= 21:
            target = min(target, highest_prev * 0.52)
        else:
            target = max(target, min(highest_prev * 0.78, DAILY_SALARY * 1.0))
    else:
        target = max(target, min(est_pressure + 2.5, DAILY_SALARY * 0.95))

    if day >= 8:
        target += 6.0
    if day >= 9 and hp <= 4:
        target += 10.0

    reserve = 0.0
    if hp >= 6 and no_water_days == 0:
        reserve = DAILY_SALARY * 0.35
    elif hp >= 4:
        reserve = DAILY_SALARY * 0.2

    max_affordable = max(0.0, budget - reserve)
    if hp <= 2 or no_water_days >= 2:
        max_affordable = budget

    bid = min(target, max_affordable)

    if hp <= 2 and bid < DAILY_SALARY * 0.9:
        bid = min(budget, DAILY_SALARY * 0.9)
    elif no_water_days >= 1 and hp <= 4 and bid < DAILY_SALARY * 0.78:
        bid = min(budget, DAILY_SALARY * 0.78)

    if bid < 0:
        bid = 0.0

    return float(min(budget, bid))

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 150
    WATER_REQ = 13
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(my_status['budget'], 50.0)
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])
    if yesterday_bids:
        avg_prev_bid = sum(yesterday_bids) / len(yesterday_bids)
        target = avg_prev_bid * 1.05
    else:
        target = DAILY_SALARY * 0.4
    if my_status['hp'] < 5:
        target = max(target, DAILY_SALARY * 0.7)
    return min(my_status['budget'], target)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    EPISODE_DAYS = 10

    my_hp = my_status['hp']
    my_budget = my_status['budget']
    current_day = day_context['day']
    current_supply = day_context['supply']

    alive_opponents = [opp_data for agent_id, opp_data in opponents_status.items() if opp_data['alive']]

    if not alive_opponents:
        return min(my_budget, DAILY_SALARY * 0.4)

    if my_hp <= 2:
        base_bid = DAILY_SALARY * 1.5
    elif my_hp <= 5:
        base_bid = DAILY_SALARY * 1.0
    else:
        base_bid = DAILY_SALARY * 0.7

    highest_prev_bid = 0
    strong_opponents_alive = False
    for agent_id, opp_data in opponents_status.items():
        if opp_data['alive']:
            if agent_id in ["Alex", "Cindy"]:
                strong_opponents_alive = True
            prev_trace = opp_data.get('previous_trace', {})
            if prev_trace and prev_trace.get('bid') is not None:
                highest_prev_bid = max(highest_prev_bid, prev_trace['bid'])

    num_alive_agents = len(alive_opponents) + 1

    if current_supply < (WATER_REQ * num_alive_agents) * 0.8:
        base_bid *= 1.2

    if highest_prev_bid > 0:
        if strong_opponents_alive or my_hp <= 5:
            base_bid = max(base_bid, highest_prev_bid + 5)
        else:
            base_bid = max(base_bid, highest_prev_bid + 1)

    final_bid = min(my_budget, base_bid)
    final_bid = max(final_bid, DAILY_SALARY * 0.1)

    return final_bid
